-- Run against reports/analytics.sqlite, generated by python -m src.pipeline.
-- Monthly demand: distinguish growth from recurring seasonality.
SELECT substr(dteday, 1, 7) AS month, SUM(cnt) AS rentals,
       ROUND(AVG(cnt), 1) AS average_daily_rentals
FROM daily_rentals GROUP BY month ORDER BY month;

-- Compare operational errors with the seasonal naive reference.
SELECT ROUND(AVG(ABS(cnt - prediction)), 2) AS model_mae,
       ROUND(AVG(ABS(cnt - lag_7)), 2) AS seasonal_baseline_mae,
       SUM(CASE WHEN prediction < cnt THEN 1 ELSE 0 END) AS underestimated_days
FROM test_predictions;

-- Which days deserve investigation? This does not establish causes.
SELECT dteday, cnt, ROUND(prediction, 0) AS predicted,
       ROUND(absolute_error, 0) AS error
FROM test_predictions ORDER BY absolute_error DESC LIMIT 10;
